SELECT i.ref_id, i.avg_rtg, f.c, f.a, i.prc, i.prc_usd
FROM items_g2 i JOIN (SELECT ref_id, COUNT(*) c, AVG(rtg) a FROM fdbk_g2 GROUP BY ref_id) f ON f.ref_id=i.ref_id
WHERE i.prc_usd>50 AND f.c>=5 AND f.a<3.0 ORDER BY f.a;

SELECT i.ref_id, i.avg_rtg, i.prc, i.prc_usd, f.c, f.a
FROM items_g2 i JOIN (SELECT ref_id, COUNT(*) c, AVG(rtg) a FROM fdbk_g2 GROUP BY ref_id) f ON f.ref_id=i.ref_id
WHERE i.prc_usd>50 AND f.c>=5 AND i.avg_rtg<3.0;
